//! Complete preceding canonical algorithm, independently compiled over old Node/Automaton.
use super::super::compact_nodes::before::{Automaton, Weighted};
use super::super::{
    physical_clone, replay_error, BTreeMap, Diagnostic, Label, Rc, ReplayBudget, ResolvedFunction,
};
pub(in crate::cleanup_plan::replay::factored) use super::closure_receiving;
use super::{app_census, inline_weighted, memo, ordered_alias, ordered_weights, successor_targets};
use inline_weighted::SmallWeighted;
type SharedWeighted = Rc<SmallWeighted>;

enum CanonicalFrame {
    Enter(SharedWeighted),
    Exit(SharedWeighted, u64, Vec<(Label, SharedWeighted)>),
}

// The caller has already paid the moved vector's complete allocated backing.
// Rc owns that vector without copying it; its counters and full enum header are
// separately acquired while all preceding owners remain fully charged.
fn own_weighted(
    function: &ResolvedFunction,
    budget: &mut ReplayBudget,
    state: Weighted,
) -> Result<SharedWeighted, Diagnostic> {
    if budget.pays_allocations() {
        budget.reserve_bytes(
            function,
            2 * std::mem::size_of::<SmallWeighted>()
                + std::mem::size_of::<Result<SharedWeighted, Diagnostic>>()
                + std::mem::size_of::<Result<(), Diagnostic>>(),
            "factored moved many weighted enum receiving",
        )?;
    }
    budget.reserve_bytes(
        function,
        physical_clone::rc_backing_bytes::<SmallWeighted>(),
        "factored weighted shared header",
    )?;
    let shared = SmallWeighted::Many(state);
    Ok(Rc::new(shared))
}

// Vec's FromIterator growth policy may round 1..3 items up to four slots.
// Build this producer through its exact precharged capacity instead.
fn weighted_successor(
    function: &ResolvedFunction,
    budget: &mut ReplayBudget,
    targets: BTreeMap<usize, u64>,
) -> Result<SharedWeighted, Diagnostic> {
    budget.reserve_array::<(usize, u64)>(
        function,
        targets.len(),
        "factored weighted successor vector",
    )?;
    let mut state = Vec::with_capacity(targets.len());
    state.extend(targets);
    own_weighted(function, budget, state)
}

fn share_weighted(
    function: &ResolvedFunction,
    budget: &mut ReplayBudget,
    state: &SharedWeighted,
) -> Result<SharedWeighted, Diagnostic> {
    let work = state
        .len()
        .checked_add(1)
        .ok_or_else(|| replay_error(function, "factored weighted state work overflowed"))?;
    budget.charge(function, work, "factored weighted state copy")?;
    // Authentication remains sticky even though this clone creates no backing.
    // The receiving frame/map slot has its own full carrier reservation.
    budget.reserve_bytes(function, 0, "factored weighted state backing")?;
    Ok(Rc::clone(state))
}

/// Bottom-up hash-consing of the weighted subset construction. A determinized
/// state's id is its accepted weight together with each label and the id of
/// the state that label leads to, so two states share an id exactly when
/// they accept every observation sequence the same number of times.
pub(in crate::cleanup_plan::replay::factored) struct Canonicalizer<'a> {
    automaton: &'a Automaton,
    sink: usize,
    closures: memo::RetainedMemo<Rc<ordered_weights::OrderedWeights>>,
    states: BTreeMap<SharedWeighted, usize>,
    ids: BTreeMap<(u64, Vec<(Label, usize)>), usize>,
    cursor: Vec<(usize, bool)>,
    frames: Vec<CanonicalFrame>,
    open: Vec<SharedWeighted>,
    scratch_paid: bool,
}

impl<'a> Canonicalizer<'a> {
    pub(in crate::cleanup_plan::replay::factored) fn new(
        automaton: &'a Automaton,
        sink: usize,
    ) -> Self {
        Self {
            automaton,
            sink,
            closures: memo::RetainedMemo::new(),
            states: BTreeMap::new(),
            ids: BTreeMap::new(),
            cursor: Vec::new(),
            frames: Vec::new(),
            open: Vec::new(),
            scratch_paid: false,
        }
    }

    /// Nodes with moves (or the sink) reachable through epsilon edges, each
    /// with its number of epsilon routes.
    // Single-request test entries pay their real owner here; equivalent()
    // instead lends one invocation owner across both roots. No wrapper gain claim.
    #[cfg(test)]
    pub(in crate::cleanup_plan::replay::factored) fn id(
        &mut self,
        function: &ResolvedFunction,
        root: Weighted,
        budget: &mut ReplayBudget,
    ) -> Result<Option<usize>, Diagnostic> {
        // Preserve the old entry's owner rejection before a fresh test-only slot
        // can query or charge a foreign payer. A valid call still pays acquisition.
        self.closures.authenticate_retained(function, budget);
        if self.closures.failed() {
            return Err(self.closures.failure());
        }
        let mut receiving = closure_receiving::ClosureReceiving::acquire(function, budget)?;
        self.id_with_receiving(function, root, budget, &mut receiving)
    }
    #[cfg(test)]
    fn successors(
        &mut self,
        function: &ResolvedFunction,
        state: &SharedWeighted,
        budget: &mut ReplayBudget,
    ) -> Result<Option<(u64, Vec<(Label, SharedWeighted)>)>, Diagnostic> {
        let mut receiving = closure_receiving::ClosureReceiving::acquire(function, budget)?;
        self.successors_with_receiving(function, state, budget, &mut receiving)
    }
    #[cfg(test)]
    fn closure(
        &mut self,
        function: &ResolvedFunction,
        root: usize,
        budget: &mut ReplayBudget,
    ) -> Result<Option<Rc<ordered_weights::OrderedWeights>>, Diagnostic> {
        self.closures.authenticate_retained(function, budget);
        if self.closures.failed() {
            return Err(self.closures.failure());
        }
        if self.closures.contains_key(&root) {
            budget.charge(function, 1, "factored closure cursor")?;
            return Ok(self.closures.get(&root).cloned());
        }
        let mut receiving = closure_receiving::ClosureReceiving::acquire(function, budget)?;
        self.closure_with_receiving(function, root, budget, &mut receiving)
    }
    fn closure_with_receiving(
        &mut self,
        function: &ResolvedFunction,
        root: usize,
        budget: &mut ReplayBudget,
        receiving: &mut closure_receiving::ClosureReceiving,
    ) -> Result<Option<Rc<ordered_weights::OrderedWeights>>, Diagnostic> {
        // Validate the held destination before any ordinary payer query.
        if !receiving.valid(function, budget) {
            self.closures.reject_after_error();
            return Err(Diagnostic::io("SPX-H006", String::new()));
        }
        self.closures.authenticate_retained(function, budget);
        if self.closures.failed() {
            return Err(self.closures.failure());
        }
        // The cached route still executes its original one cursor work debit.
        // It constructs neither a cursor Vec nor a closure_inner Result
        // receiver. Cold memo authentication still pays its real Result; warm
        // authentication writes directly into its already paid refusal slot.
        if self.closures.contains_key(&root) {
            budget.charge(function, 1, "factored closure cursor")?;
            return Ok(self.closures.get(&root).cloned());
        }
        if budget.pays_allocations() {
            budget.reserve_bytes(
                function,
                closure_receiving::ClosureReceiving::PER_MISS_CONTROLS
                    + std::mem::size_of::<Result<(), Diagnostic>>()
                    + std::mem::size_of::<usize>(),
                "factored closure scratch receiving",
            )?;
        }
        self.prepare_scratch(function, budget)?;
        receiving.begin();
        #[cfg(test)]
        closure_receiving::note_producer();
        self.closure_inner_into(function, root, budget, receiving);
        self.cursor.clear();
        assert!(receiving.ready, "unit producer settled exactly once");
        receiving.ready = false;
        // Do not construct an Option<Diagnostic> receiver on success.
        if receiving.refusal.is_some() {
            return Err(receiving.refusal.take().expect("published refusal"));
        }
        Ok(receiving.value.take())
    }

    fn closure_inner_into(
        &mut self,
        function: &ResolvedFunction,
        root: usize,
        budget: &mut ReplayBudget,
        receiving: &mut closure_receiving::ClosureReceiving,
    ) {
        macro_rules! attempt {
            ($operation:expr) => {
                match $operation {
                    Ok(value) => value,
                    Err(error) => {
                        receiving.refuse(error);
                        return;
                    }
                }
            };
        }
        attempt!(budget.reserve_vec(
            function,
            &mut self.cursor,
            1,
            "factored closure initial cursor",
        ));
        self.cursor.push((root, false));
        while let Some((node, expanded)) = self.cursor.pop() {
            attempt!(budget.charge(function, 1, "factored closure cursor"));
            if self.closures.contains_key(&node) {
                continue;
            }
            let state = &self.automaton.nodes[node];
            if !expanded {
                attempt!(budget.reserve_vec(
                    function,
                    &mut self.cursor,
                    1,
                    "factored closure cursors"
                ));
                self.cursor.push((node, true));
                for target in &state.epsilon {
                    if !self.closures.contains_key(target) {
                        attempt!(budget.reserve_vec(
                            function,
                            &mut self.cursor,
                            1,
                            "factored closure cursors",
                        ));
                        self.cursor.push((*target, false));
                    }
                }
                continue;
            }
            // Exactly one immutable epsilon child contributes the complete map.
            // Sink/own-move/duplicate-edge and all other shapes keep the full
            // general producer below, including checked route accumulation.
            if node != self.sink && state.moves.is_empty() && state.epsilon.len() == 1 {
                #[cfg(test)]
                app_census::eligible();
                let Some(inner) = self.closures.get(&state.epsilon[0]) else {
                    receiving.refuse(replay_error(function, "cleanup CFG contains a cycle"));
                    return;
                };
                #[cfg(test)]
                app_census::child_ready(inner.len());
                let shared = match ordered_alias::share(function, inner, budget) {
                    Ok(shared) => shared,
                    Err(error) => {
                        self.closures.reject_after_error();
                        receiving.refuse(error);
                        return;
                    }
                };
                #[cfg(test)]
                app_census::acquired();
                attempt!(self
                    .closures
                    .insert_retained(function, node, budget, || shared));
                #[cfg(test)]
                app_census::published();
                continue;
            }
            if budget.pays_allocations() {
                attempt!(budget.reserve_bytes(
                    function,
                    ordered_weights::OrderedWeights::CONTROLS,
                    "factored ordered closure controls",
                ));
            }
            let mut closure = ordered_weights::OrderedWeights::new();
            if !state.moves.is_empty() || node == self.sink {
                if closure.needs_capacity() {
                    attempt!(closure.grow(function, budget));
                }
                closure.insert_prepaid(node, 1_u64);
            }
            for target in &state.epsilon {
                let Some(inner) = self.closures.get(target) else {
                    receiving.refuse(replay_error(function, "cleanup CFG contains a cycle"));
                    return;
                };
                for (inner_node, routes) in inner.iter() {
                    attempt!(budget.charge(function, 1, "factored closure route addition"));
                    if closure.get(inner_node).is_none() {
                        if closure.needs_capacity() {
                            attempt!(closure.grow(function, budget));
                        }
                        closure.insert_prepaid(*inner_node, 0_u64);
                    }
                    let slot = closure
                        .get_mut(inner_node)
                        .expect("inserted ordered weight");
                    let Some(sum) = slot.checked_add(*routes) else {
                        receiving.complete(None);
                        return;
                    };
                    *slot = sum;
                }
            }
            attempt!(budget.charge(
                function,
                closure.len().saturating_add(1),
                "factored skeleton closure",
            ));
            attempt!(budget.reserve_bytes(
                function,
                physical_clone::rc_backing_bytes::<ordered_weights::OrderedWeights>(),
                "factored closure shared header",
            ));
            attempt!(self
                .closures
                .insert_retained(function, node, budget, || Rc::new(closure)));
        }
        receiving.complete(self.closures.get(&root).cloned());
    }

    /// The accepted weight of `state` and its weighted successor per label.
    #[allow(clippy::type_complexity)]
    fn successors_with_receiving(
        &mut self,
        function: &ResolvedFunction,
        state: &SharedWeighted,
        budget: &mut ReplayBudget,
        receiving: &mut closure_receiving::ClosureReceiving,
    ) -> Result<Option<(u64, Vec<(Label, SharedWeighted)>)>, Diagnostic> {
        if budget.pays_allocations() {
            budget.reserve_bytes(
                function,
                ordered_weights::Closed::CONTROLS,
                "factored ordered closed receiving controls",
            )?;
        }
        let closed = if let [(node, 1)] = state.as_slice() {
            let Some(closure) = self.closure_with_receiving(function, *node, budget, receiving)?
            else {
                return Ok(None);
            };
            // The old empty accumulator saw every unique closure entry once.
            // Execute its checked arithmetic and EACH original work debit,
            // before moving the authenticated immutable owner into the view.
            for (_, routes) in closure.iter() {
                let Some(_sum) = routes
                    .checked_mul(1)
                    .and_then(|product| 0_u64.checked_add(product))
                else {
                    return Ok(None);
                };
                budget.charge(function, 1, "factored weighted route addition")?;
            }
            ordered_weights::Closed::Borrowed(closure)
        } else {
            if budget.pays_allocations() {
                budget.reserve_bytes(
                    function,
                    ordered_weights::OrderedWeights::CONTROLS,
                    "factored ordered accumulator controls",
                )?;
            }
            let mut closed = ordered_weights::OrderedWeights::new();
            for (node, weight) in state.iter() {
                let Some(closure) =
                    self.closure_with_receiving(function, *node, budget, receiving)?
                else {
                    return Ok(None);
                };
                for (inner, routes) in closure.iter() {
                    let Some(sum) = routes.checked_mul(*weight).and_then(|product| {
                        closed.get(inner).copied().unwrap_or(0).checked_add(product)
                    }) else {
                        return Ok(None);
                    };
                    budget.charge(function, 1, "factored weighted route addition")?;
                    if closed.get(inner).is_none() {
                        if closed.needs_capacity() {
                            closed.grow(function, budget)?;
                        }
                        closed.insert_prepaid(*inner, 0_u64);
                    }
                    *closed.get_mut(inner).expect("inserted ordered weight") = sum;
                }
            }
            ordered_weights::Closed::Owned(closed)
        };
        let closed = closed.weights();
        let accepted = closed.get(&self.sink).copied().unwrap_or(0);
        if budget.pays_allocations() {
            budget.reserve_bytes(
                function,
                std::mem::size_of::<BTreeMap<Label, successor_targets::Targets>>()
                    + std::mem::size_of::<Option<&mut successor_targets::Targets>>(),
                "factored successor label receiving controls",
            )?;
        }
        let mut successors = BTreeMap::<Label, successor_targets::Targets>::new();
        for (node, weight) in closed.iter() {
            let moves = &self.automaton.nodes[*node].moves;
            budget.charge(
                function,
                moves.len().saturating_add(1),
                "factored skeleton subset construction",
            )?;
            for (label, child) in moves {
                if !successors.contains_key(label) {
                    budget.reserve_btree_node::<Label, successor_targets::Targets>(
                        function,
                        "factored successor label node",
                    )?;
                    if budget.pays_allocations() {
                        budget.reserve_bytes(
                            function,
                            2 * std::mem::size_of::<successor_targets::Targets>()
                                + std::mem::size_of::<Option<u64>>()
                                + std::mem::size_of::<Option<successor_targets::Targets>>(),
                            "factored inline singleton target initializer and receiving",
                        )?;
                    }
                    budget.reserve_bytes(
                        function,
                        0,
                        "factored singleton target authentication",
                    )?;
                    let weight = 0_u64
                        .checked_add(*weight)
                        .expect("zero plus u64 cannot overflow");
                    successors.insert(
                        label.clone(),
                        successor_targets::Targets::One {
                            child: *child,
                            weight,
                        },
                    );
                } else {
                    let targets = successors.get_mut(label).expect("existing label");
                    match targets {
                        successor_targets::Targets::One {
                            child: first,
                            weight: total,
                        } if *first == *child => {
                            // Same repeated-child checked_add before any later
                            // target acquisition or error, as in the old map.
                            let Some(sum) = total.checked_add(*weight) else {
                                return Ok(None);
                            };
                            *total = sum;
                        }
                        successor_targets::Targets::One {
                            child: first,
                            weight: total,
                        } => {
                            assert_ne!(*first, *child);
                            if budget.pays_allocations() {
                                budget.reserve_bytes(
                                    function,
                                    2 * std::mem::size_of::<BTreeMap<usize, u64>>()
                                        + std::mem::size_of::<successor_targets::Targets>()
                                        + 2 * std::mem::size_of::<Option<u64>>()
                                        + 2 * std::mem::size_of::<(usize, u64)>(),
                                    "factored inline successor promotion carriers",
                                )?;
                            }
                            budget.reserve_bytes(
                                function,
                                0,
                                "factored successor target promotion authentication",
                            )?;
                            budget.reserve_btree_node::<usize, u64>(
                                function,
                                "factored successor target node",
                            )?;
                            budget.reserve_btree_node::<usize, u64>(
                                function,
                                "factored successor target node",
                            )?;
                            let mut promoted = BTreeMap::new();
                            promoted.insert(*first, *total);
                            let sum = 0_u64
                                .checked_add(*weight)
                                .expect("zero plus u64 cannot overflow");
                            promoted.insert(*child, sum);
                            *targets = successor_targets::Targets::Many(promoted);
                        }
                        successor_targets::Targets::Many(targets) => {
                            if !targets.contains_key(child) {
                                budget.reserve_btree_node::<usize, u64>(
                                    function,
                                    "factored successor target node",
                                )?;
                            }
                            let slot = targets.entry(*child).or_insert(0);
                            let Some(sum) = slot.checked_add(*weight) else {
                                return Ok(None);
                            };
                            *slot = sum;
                        }
                    }
                }
            }
        }
        budget.reserve_array::<(Label, SharedWeighted)>(
            function,
            successors.len(),
            "factored successor vector",
        )?;
        let mut result = Vec::with_capacity(successors.len());
        // Do not initialize an owning map iterator or its receiving tuple on
        // the empty route. Zero-byte vector authentication above still runs.
        if !successors.is_empty() {
            if budget.pays_allocations() {
                budget.reserve_bytes(
                    function,
                    std::mem::size_of::<
                        std::collections::btree_map::IntoIter<Label, successor_targets::Targets>,
                    >() + std::mem::size_of::<Option<(Label, successor_targets::Targets)>>()
                        + std::mem::size_of::<(Label, successor_targets::Targets)>(),
                    "factored successor target iterator receiving",
                )?;
            }
            for (label, targets) in successors {
                if budget.pays_allocations() {
                    budget.reserve_bytes(
                        function,
                        2 * std::mem::size_of::<SharedWeighted>()
                            + std::mem::size_of::<(usize, u64)>(),
                        "factored inline successor finish receiving",
                    )?;
                }
                budget.reserve_bytes(
                    function,
                    0,
                    "factored successor target finish authentication",
                )?;
                let state = match targets {
                    successor_targets::Targets::One { child, weight } => {
                        if budget.pays_allocations() {
                            budget.reserve_bytes(
                                function,
                                2 * std::mem::size_of::<SmallWeighted>()
                                    + std::mem::size_of::<[(usize, u64); 1]>()
                                    + std::mem::size_of::<Result<(), Diagnostic>>(),
                                "factored inline weighted enum and array receiving",
                            )?;
                        }
                        budget.reserve_bytes(
                            function,
                            physical_clone::rc_backing_bytes::<SmallWeighted>(),
                            "factored weighted shared header",
                        )?;
                        let singleton = SmallWeighted::One([(child, weight)]);
                        Rc::new(singleton)
                    }
                    successor_targets::Targets::Many(targets) => {
                        // The remaining fallible weighted producer still has
                        // its real map argument and Result receiving carrier.
                        if budget.pays_allocations() {
                            budget.reserve_bytes(
                                function,
                                std::mem::size_of::<BTreeMap<usize, u64>>()
                                    + std::mem::size_of::<Vec<(usize, u64)>>()
                                    + std::mem::size_of::<Result<SharedWeighted, Diagnostic>>(),
                                "factored many weighted producer receiving",
                            )?;
                        }
                        weighted_successor(function, budget, targets)?
                    }
                };
                result.push((label, state));
            }
        }
        Ok(Some((accepted, result)))
    }

    pub(in crate::cleanup_plan::replay::factored) fn id_with_receiving(
        &mut self,
        function: &ResolvedFunction,
        root: Weighted,
        budget: &mut ReplayBudget,
        receiving: &mut closure_receiving::ClosureReceiving,
    ) -> Result<Option<usize>, Diagnostic> {
        #[cfg(test)]
        tests::note_actual_entry(budget);
        // Authenticate even when states already contains the requested root.
        // One equivalent() call holds this function and budget borrowed across
        // both roots; no closure/cache view leaves that invocation.
        // Validate the held destination before any ordinary payer query.
        if !receiving.valid(function, budget) {
            self.closures.reject_after_error();
            return Err(Diagnostic::io("SPX-H006", String::new()));
        }
        self.closures.authenticate_retained(function, budget);
        if self.closures.failed() {
            return Err(self.closures.failure());
        }
        if budget.pays_allocations() {
            budget.reserve_bytes(
                function,
                std::mem::size_of::<Result<Option<usize>, Diagnostic>>()
                    + std::mem::size_of::<Weighted>()
                    + std::mem::size_of::<Result<(), Diagnostic>>(),
                "factored canonical scratch receiving and moved root",
            )?;
        }
        self.prepare_scratch(function, budget)?;
        let result = self.id_inner(function, root, budget, receiving);
        // Retain capacity, never owned references, across either root and all
        // success, arithmetic, work, physical and semantic failure exits.
        self.cursor.clear();
        self.frames.clear();
        self.open.clear();
        result
    }

    fn prepare_scratch(
        &mut self,
        function: &ResolvedFunction,
        budget: &mut ReplayBudget,
    ) -> Result<(), Diagnostic> {
        if !self.scratch_paid {
            if budget.pays_allocations() {
                budget.reserve_bytes(
                    function,
                    std::mem::size_of::<Vec<(usize, bool)>>()
                        + std::mem::size_of::<Vec<CanonicalFrame>>()
                        + std::mem::size_of::<Vec<SharedWeighted>>()
                        + std::mem::size_of::<bool>(),
                    "factored retained canonical scratch controls",
                )?;
            }
            self.scratch_paid = true;
        }
        Ok(())
    }

    fn id_inner(
        &mut self,
        function: &ResolvedFunction,
        root: Weighted,
        budget: &mut ReplayBudget,
        receiving: &mut closure_receiving::ClosureReceiving,
    ) -> Result<Option<usize>, Diagnostic> {
        budget.reserve_vec(
            function,
            &mut self.frames,
            1,
            "factored canonical initial frame",
        )?;
        let root = own_weighted(function, budget, root)?;
        let root_copy = share_weighted(function, budget, &root)?;
        self.frames.push(CanonicalFrame::Enter(root_copy));
        while let Some(frame) = self.frames.pop() {
            budget.charge(function, 1, "factored canonical frame")?;
            match frame {
                CanonicalFrame::Enter(state) => {
                    if self.states.contains_key(&state) {
                        continue;
                    }
                    if self.open.contains(&state) {
                        return Err(replay_error(function, "cleanup CFG contains a cycle"));
                    }
                    budget.reserve_vec(
                        function,
                        &mut self.open,
                        1,
                        "factored retained open-state identity slots",
                    )?;
                    self.open.push(share_weighted(function, budget, &state)?);
                    let Some((accepted, successors)) =
                        self.successors_with_receiving(function, &state, budget, receiving)?
                    else {
                        return Ok(None);
                    };
                    let child_count = successors.len();
                    budget.reserve_vec(
                        function,
                        &mut self.frames,
                        1,
                        "factored canonical exit frame",
                    )?;
                    let exit_index = self.frames.len();
                    self.frames
                        .push(CanonicalFrame::Exit(state, accepted, successors));
                    for index in 0..child_count {
                        let CanonicalFrame::Exit(_, _, successors) = &self.frames[exit_index]
                        else {
                            unreachable!("canonical exit retained below child frames");
                        };
                        let child = share_weighted(function, budget, &successors[index].1)?;
                        budget.reserve_vec(
                            function,
                            &mut self.frames,
                            1,
                            "factored canonical child frames",
                        )?;
                        self.frames.push(CanonicalFrame::Enter(child));
                    }
                }
                CanonicalFrame::Exit(state, accepted, successors) => {
                    self.open.retain(|entry| entry != &state);
                    budget.charge(
                        function,
                        successors.len(),
                        "factored canonical signature construction",
                    )?;
                    budget.reserve_array::<(Label, usize)>(
                        function,
                        successors.len(),
                        "factored canonical signature vector",
                    )?;
                    let mut key = Vec::with_capacity(successors.len());
                    for (label, child) in successors {
                        let Some(id) = self.states.get(&child) else {
                            return Err(replay_error(function, "cleanup CFG contains a cycle"));
                        };
                        key.push((label, *id));
                    }
                    let key = (accepted, key);
                    let id = match self.ids.get(&key) {
                        Some(id) => *id,
                        None => {
                            budget.reserve_btree_node::<(u64, Vec<(Label, usize)>), usize>(
                                function,
                                "factored canonical signature node",
                            )?;
                            let id = self.ids.len();
                            self.ids.insert(key, id);
                            id
                        }
                    };
                    if !self.states.contains_key(&state) {
                        budget.reserve_btree_node::<SharedWeighted, usize>(
                            function,
                            "factored canonical state memo node",
                        )?;
                    }
                    self.states.insert(state, id);
                }
            }
        }
        Ok(self.states.get(&root).copied())
    }
}

mod tests {
    use super::ReplayBudget;
    thread_local! {
        static ACTUAL_ENTRIES: std::cell::Cell<Option<(usize, usize)>> = const { std::cell::Cell::new(None) };
    }
    struct ActualEntries(Option<(usize, usize)>);
    impl ActualEntries {
        fn open(limit: usize) -> Self {
            Self(ACTUAL_ENTRIES.with(|state| state.replace(Some((limit, 0)))))
        }
        fn calls(&self) -> usize {
            ACTUAL_ENTRIES.with(|state| state.get().unwrap().1)
        }
    }
    impl Drop for ActualEntries {
        fn drop(&mut self) {
            ACTUAL_ENTRIES.with(|state| state.set(self.0));
        }
    }
    pub(in crate::cleanup_plan::replay::factored) fn note_actual_entry(budget: &mut ReplayBudget) {
        ACTUAL_ENTRIES.with(|state| {
            if let Some((limit, calls)) = state.get() {
                if calls == 0 {
                    budget.remaining = limit;
                }
                state.set(Some((limit, calls + 1)));
            }
        });
    }
}

edits.new:
//! Factored typed-control skeleton comparison.
//!
//! The enumerating comparison materializes every terminal path of the typed
//! HIR and of the cleanup CFG and compares the sorted multisets. Independent
//! decisions in sequence multiply that count (2^N for N independent `if`s,
//! `&&` operands, or scalar `match`es), although a decision that leaves the
//! cleanup state unchanged contributes nothing a single path would not.
//!
//! This module decides the same multiset equality without enumerating the
//! product:
//!
//! * The typed-HIR skeleton is derived by the unchanged walk with path-state
//!   merging enabled: whenever paths are sequenced, paths whose cleanup state
//!   (owned source, failure, residual, and call commit list) is identical are
//!   merged into one path carrying the union of their observation sequences.
//!   Every later skeleton step reads only that state, so the merged walk
//!   denotes exactly the enumerated paths, and its size follows the number of
//!   distinct cleanup states rather than the number of decision combinations.
//!   Lexical functions restrict those merges to independently identified Copy
//!   expression scopes; every abrupt/failure/owning state remains separate.
//! * Both the merged HIR paths and the cleanup CFG become acyclic automata
//!   over skeleton observations, each accepting sequence ending in one
//!   terminal label.
//! * Bottom-up hash-consing of the weighted subset construction assigns two
//!   states the same id exactly when they accept every sequence the same
//!   number of times, so equal roots prove equal path multisets.
use super::super::super::skeleton_work::{ObservationDag, ObservationDagKind};
use super::super::super::*;
use super::super::canonical_shared::before_nodes as canonical_shared;
use std::rc::Rc;
#[path = "borrowed.rs"]
mod borrowed_canonical;
#[path = "../../instrumentation.rs"]
mod instrumentation;
#[path = "storage.rs"]
mod storage;
use super::super::{copy_regions, dag_memo, oracle_hook};
use storage::{memo_insert, push_end, push_frame, reserve_transition_observation};

/// Path count above which the factored comparison replaces enumeration.
const FACTORED_PATH_THRESHOLD: usize = 4_096;

// Byte-exact original Label shared; old Node/Automaton remain independent.
use super::super::Label;

#[derive(Default)]
pub(in crate::cleanup_plan::replay::factored) struct Node {
    pub(in crate::cleanup_plan::replay::factored) moves: Vec<(Label, usize)>,
    pub(in crate::cleanup_plan::replay::factored) epsilon: Vec<usize>,
}

/// Semantic nonselection remains false; a physical scratch refusal is sticky
/// and must reach the caller instead of becoming enumerating-route authority.
pub(super) fn selected_paid(
    function: &ResolvedFunction,
    cfg_paths: usize,
    semantic_paths: usize,
    budget: &mut ReplayBudget,
) -> Result<bool, Diagnostic> {
    if cfg_paths <= FACTORED_PATH_THRESHOLD && semantic_paths <= FACTORED_PATH_THRESHOLD {
        return Ok(false);
    }
    match structural_control::validate_ordinary_cfg(function, budget) {
        Ok(()) => Ok(true),
        Err(error) if budget.refusal_spent || crate::bounded_output::active_refused() => Err(error),
        Err(_) => Ok(false),
    }
}

#[cfg(test)]
/// `true` when this function's typed-control skeleton is compared factored.
/// A cyclic CFG saturates the path census and keeps the census diagnostic.
pub(super) fn selected(
    function: &ResolvedFunction,
    cfg_paths: usize,
    semantic_paths: usize,
) -> bool {
    (cfg_paths > FACTORED_PATH_THRESHOLD || semantic_paths > FACTORED_PATH_THRESHOLD)
        && validate_reachable_acyclic_cfg(function).is_ok()
}

/// Run the factored comparison when it is selected. `Ok(true)` means the
/// skeleton is authenticated; `Ok(false)` leaves the enumerating comparison
/// in charge.
#[cfg(test)]
pub(super) fn validate(
    program: &dyn crate::cleanup::ReplayContext,
    function: &ResolvedFunction,
    budget: &mut ReplayBudget,
) -> Result<bool, Diagnostic> {
    validate_with_index(program, function, budget, None)
}
pub(super) fn validate_with_index(
    program: &dyn crate::cleanup::ReplayContext,
    function: &ResolvedFunction,
    budget: &mut ReplayBudget,
    helpers: Option<&crate::loop_calls::byte_writer::ModuleIndex<'_>>,
) -> Result<bool, Diagnostic> {
    validate_with_index_storage(program, function, budget, helpers, None)
}
pub(super) fn validate_with_index_storage<'hir>(
    program: &'hir dyn crate::cleanup::ReplayContext,
    function: &'hir ResolvedFunction,
    budget: &mut ReplayBudget,
    helpers: Option<&crate::loop_calls::byte_writer::ModuleIndex<'hir>>,
    continuations: Option<&mut continuation_storage::Storage<'hir>>,
) -> Result<bool, Diagnostic> {
    let cfg_paths = branch_sensitive_cfg_bounds(function)?.terminal_paths;
    let semantic_paths = hir_terminal_path_bound(function)?;
    if !selected_paid(
        function,
        cfg_paths,
        semantic_paths,
        &mut ReplayBudget::new(),
    )? {
        #[cfg(test)]
        oracle_hook::cross_check_with_storage(program, function, budget, continuations)?;
        return Ok(false);
    }
    match compare_with_index_storage(program, function, budget, helpers, continuations) {
        Ok(Some(true)) => Ok(true),
        Ok(Some(false)) => Err(skeleton_mismatch(function)),
        verdict => {
            if cfg_paths <= MAX_REPLAY_PATHS && semantic_paths <= MAX_REPLAY_PATHS {
                // Enumeration still fits; an attempted factored comparison
                // keeps every work and physical debit already spent.
                return Ok(false);
            }
            match verdict {
                Err(error) if !error.message.contains("budget") => Err(error),
                _ => path_summary::path_budget_errors(function, cfg_paths, semantic_paths)
                    .map(|()| false),
            }
        }
    }
}

fn skeleton_mismatch(function: &ResolvedFunction) -> Diagnostic {
    replay_error(
        function,
        "cleanup CFG decision or ownership-event sequence disagrees with typed HIR",
    )
}

/// `Some(equal)`, or `None` when a path multiplicity overflows.
#[cfg(test)]
pub(super) fn compare(
    program: &dyn crate::cleanup::ReplayContext,
    function: &ResolvedFunction,
    budget: &mut ReplayBudget,
) -> Result<Option<bool>, Diagnostic> {
    compare_with_index(program, function, budget, None)
}
pub(super) fn compare_with_index(
    program: &dyn crate::cleanup::ReplayContext,
    function: &ResolvedFunction,
    budget: &mut ReplayBudget,
    helpers: Option<&crate::loop_calls::byte_writer::ModuleIndex<'_>>,
) -> Result<Option<bool>, Diagnostic> {
    compare_with_index_storage(program, function, budget, helpers, None)
}
fn compare_with_index_storage<'hir>(
    program: &'hir dyn crate::cleanup::ReplayContext,
    function: &'hir ResolvedFunction,
    budget: &mut ReplayBudget,
    helpers: Option<&crate::loop_calls::byte_writer::ModuleIndex<'hir>>,
    continuations: Option<&mut continuation_storage::Storage<'hir>>,
) -> Result<Option<bool>, Diagnostic> {
    let BuiltComparison {
        automaton,
        sink,
        hir_root,
        plan_root,
    } = build_comparison(program, function, budget, helpers, continuations)?;

    #[cfg(test)]
    if budget.oracle_lease().is_some() {
        // The exact reconstructed automaton is unchanged. An Oracle account
        // pays the full general label order; it grants no borrowed-helper lease.
        let mut canonical =
            borrowed_canonical::BorrowedCanonicalizer::new(function, &automaton, sink, budget)?;
        budget.reserve_array::<(usize, u64)>(function, 1, "oracle HIR weighted root")?;
        let Some(hir) = canonical.id(function, vec![(hir_root, 1)], budget)? else {
            return Ok(None);
        };
        budget.reserve_array::<(usize, u64)>(function, 1, "oracle plan weighted root")?;
        let Some(plan) = canonical.id(function, vec![(plan_root, 1)], budget)? else {
            return Ok(None);
        };
        return Ok(Some(hir == plan));
    }

    #[cfg(test)]
    if let Some(lease) = program.borrowed_helper_lease(function) {
        lease.validate(program, function, budget)?;
        let mut canonical =
            borrowed_canonical::BorrowedCanonicalizer::new(function, &automaton, sink, budget)?;
        budget.reserve_array::<(usize, u64)>(function, 1, "borrowed HIR weighted root")?;
        let Some(hir) = canonical.id(function, vec![(hir_root, 1)], budget)? else {
            return Ok(None);
        };
        budget.reserve_array::<(usize, u64)>(function, 1, "borrowed plan weighted root")?;
        let Some(plan) = canonical.id(function, vec![(plan_root, 1)], budget)? else {
            return Ok(None);
        };
        return Ok(Some(hir == plan));
    }

    let mut canonical = canonical_shared::Canonicalizer::new(&automaton, sink);
    if budget.pays_allocations() {
        budget.reserve_bytes(
            function,
            canonical_shared::closure_receiving::ClosureReceiving::DIRECT_CONTROLS,
            "factored held closure invocation controls",
        )?;
    }
    let mut receiving =
        canonical_shared::closure_receiving::ClosureReceiving::from_prepaid(function, budget);
    budget.reserve_array::<(usize, u64)>(function, 1, "factored HIR weighted root")?;
    let Some(hir) =
        canonical.id_with_receiving(function, vec![(hir_root, 1)], budget, &mut receiving)?
    else {
        return Ok(None);
    };
    budget.reserve_array::<(usize, u64)>(function, 1, "factored plan weighted root")?;
    let Some(plan) =
        canonical.id_with_receiving(function, vec![(plan_root, 1)], budget, &mut receiving)?
    else {
        return Ok(None);
    };
    Ok(Some(hir == plan))
}

struct BuiltComparison {
    automaton: Automaton,
    sink: usize,
    hir_root: usize,
    plan_root: usize,
}

/// Reconstruct both exact observation languages once, retaining every debit.
/// The exact strategy census borrows this same physical owner; it never
/// retries construction after choosing a representation.
fn build_comparison<'hir>(
    program: &'hir dyn crate::cleanup::ReplayContext,
    function: &'hir ResolvedFunction,
    budget: &mut ReplayBudget,
    helpers: Option<&crate::loop_calls::byte_writer::ModuleIndex<'hir>>,
    continuations: Option<&mut continuation_storage::Storage<'hir>>,
) -> Result<BuiltComparison, Diagnostic> {
    // Both independent constructors debit skeleton helpers as well as ordinary
    // constructors. Keep one active allowance through the HIR walk AND plan
    // automaton construction; the held program reservation belongs to other
    // enumerated functions and cannot pay for this deferred attempt.
    #[cfg(test)]
    instrumentation::begin(function, budget);
    let skeleton_reserve = budget.skeleton_remaining;
    budget.skeleton_remaining = std::mem::take(&mut budget.remaining);
    budget.lent_skeleton = true;
    let result = (|| {
        budget.merge_paths = true;
        let hir_paths = hir_skeleton_paths_with_index_storage(
            program,
            function,
            budget,
            helpers,
            continuations,
        );
        budget.merge_paths = false;
        #[cfg(test)]
        instrumentation::phase(
            function,
            budget,
            "HIR skeleton",
            hir_paths.as_ref().map(|paths| paths.as_slice()).ok(),
        );
        let hir_paths = hir_paths?;

        let mut automaton = Automaton::default();
        let sink = automaton.node(function, budget)?;
        let success = automaton.end(function, budget, sink, SkeletonTerminal::Success)?;
        let failure = automaton.end(function, budget, sink, SkeletonTerminal::Failure)?;
        let latch = automaton.end(function, budget, sink, SkeletonTerminal::LoopLatch)?;
        let hir_root = automaton.node(function, budget)?;
        let mut memo = dag_memo::new(program, function, budget)?;
        for path in &hir_paths {
            let end = automaton.add_observations(
                function,
                &path.observations,
                hir_root,
                &mut memo,
                budget,
            )?;
            let terminal = match path.terminal {
                SkeletonTerminal::Success => success,
                SkeletonTerminal::Failure => failure,
                SkeletonTerminal::LoopLatch => latch,
            };
            automaton.epsilon(function, budget, end, terminal)?;
        }
        #[cfg(test)]
        instrumentation::phase(function, budget, "HIR automaton", None);
        let plan_root = automaton.add_plan(function, success, failure, latch, budget)?;
        #[cfg(test)]
        instrumentation::phase(function, budget, "plan automaton", None);
        Ok(BuiltComparison {
            automaton,
            sink,
            hir_root,
            plan_root,
        })
    })();
    // Restore only the unused allowance. Successful debits from either
    // constructor remain spent, including an attempt ending in refusal.
    budget.merge_paths = false;
    budget.lent_skeleton = false;
    budget.remaining = std::mem::replace(&mut budget.skeleton_remaining, skeleton_reserve);
    #[cfg(test)]
    instrumentation::phase(
        function,
        budget,
        if result.is_ok() {
            "constructed"
        } else {
            "constructor refusal"
        },
        None,
    );
    result
}

#[path = "strategy.rs"]
pub(super) mod strategy;

#[derive(Default)]
pub(in crate::cleanup_plan::replay::factored) struct Automaton {
    pub(in crate::cleanup_plan::replay::factored) nodes: Vec<Node>,
}

enum BuildFrame<'d> {
    Visit(&'d Rc<ObservationDag>, usize),
    Seq(&'d Rc<ObservationDag>, usize),
    Cat(&'d Rc<ObservationDag>, usize, usize),
    Alt(&'d Rc<ObservationDag>, usize, usize),
}

impl Automaton {
    fn node(
        &mut self,
        function: &ResolvedFunction,
        budget: &mut ReplayBudget,
    ) -> Result<usize, Diagnostic> {
        budget.charge(function, 1, "factored automaton node construction")?;
        budget.reserve_vec(function, &mut self.nodes, 1, "factored automaton nodes")?;
        self.nodes.push(Node::default());
        #[cfg(test)]
        instrumentation::node();
        Ok(self.nodes.len() - 1)
    }

    fn movement(
        &mut self,
        function: &ResolvedFunction,
        budget: &mut ReplayBudget,
        from: usize,
        label: Label,
        to: usize,
    ) -> Result<(), Diagnostic> {
        budget.charge(function, 1, "factored automaton labelled movement")?;
        budget.reserve_vec(
            function,
            &mut self.nodes[from].moves,
            1,
            "factored automaton moves",
        )?;
        self.nodes[from].moves.push((label, to));
        #[cfg(test)]
        instrumentation::edge();
        Ok(())
    }

    fn epsilon(
        &mut self,
        function: &ResolvedFunction,
        budget: &mut ReplayBudget,
        from: usize,
        to: usize,
    ) -> Result<(), Diagnostic> {
        budget.charge(function, 1, "factored automaton epsilon movement")?;
        budget.reserve_vec(
            function,
            &mut self.nodes[from].epsilon,
            1,
            "factored automaton epsilon moves",
        )?;
        self.nodes[from].epsilon.push(to);
        #[cfg(test)]
        instrumentation::edge();
        Ok(())
    }

    fn observation(
        &mut self,
        function: &ResolvedFunction,
        budget: &mut ReplayBudget,
        from: usize,
        observation: SkeletonObservation,
        to: usize,
    ) -> Result<(), Diagnostic> {
        budget.reserve_bytes(
            function,
            physical_clone::observation_rc_bytes(),
            "factored automaton observation header",
        )?;
        self.movement(
            function,
            budget,
            from,
            Label::Observation(Rc::new(observation)),
            to,
        )
    }

    fn end(
        &mut self,
        function: &ResolvedFunction,
        budget: &mut ReplayBudget,
        sink: usize,
        terminal: SkeletonTerminal,
    ) -> Result<usize, Diagnostic> {
        let node = self.node(function, budget)?;
        self.movement(function, budget, node, Label::End(terminal), sink)?;
        Ok(node)
    }

    fn chain(
        &mut self,
        function: &ResolvedFunction,
        budget: &mut ReplayBudget,
        mut end: usize,
        items: &[Rc<SkeletonObservation>],
    ) -> Result<usize, Diagnostic> {
        for item in items {
            let next = self.node(function, budget)?;
            self.movement(
                function,
                budget,
                end,
                Label::Observation(item.clone()),
                next,
            )?;
            end = next;
        }
        Ok(end)
    }

    /// Build `observations` forward from `start` and return its end node.
    /// A shared DAG node is built once per start node, so a merged prefix
    /// that many later paths extend exists once in the automaton.
    fn add_observations(
        &mut self,
        function: &ResolvedFunction,
        observations: &Observations,
        start: usize,
        memo: &mut dag_memo::Memo,
        budget: &mut ReplayBudget,
    ) -> Result<usize, Diagnostic> {
        let (prefix, items) = observations.parts();
        let mut end = start;
        if let Some(prefix) = prefix {
            end = self.add_dag(function, prefix, start, memo, budget)?;
        }
        budget.charge(
            function,
            items.len().saturating_add(1),
            "factored HIR automaton",
        )?;
        self.chain(function, budget, end, items)
    }

    fn add_dag(
        &mut self,
        function: &ResolvedFunction,
        root: &Rc<ObservationDag>,
        start: usize,
        memo: &mut dag_memo::Memo,
        budget: &mut ReplayBudget,
    ) -> Result<usize, Diagnostic> {
        let key = dag_memo::key;
        budget.reserve_array::<BuildFrame<'_>>(function, 1, "factored DAG initial frame")?;
        let mut frames = vec![BuildFrame::Visit(root, start)];
        let mut ends = Vec::<usize>::new();
        while let Some(frame) = frames.pop() {
            match frame {
                BuildFrame::Visit(dag, start) => {
                    budget.charge(function, 1, "factored HIR automaton")?;
                    let retained = dag_memo::get(function, memo, &key(dag, start), budget)?;
                    #[cfg(test)]
                    instrumentation::visit(dag, retained.is_some());
                    if let Some(end) = retained {
                        push_end(function, budget, &mut ends, end)?;
                        continue;
                    }
                    match &dag.kind {
                        ObservationDagKind::Seq(prefix, _) => {
                            push_frame(function, budget, &mut frames, BuildFrame::Seq(dag, start))?;
                            match prefix {
                                Some(prefix) => push_frame(
                                    function,
                                    budget,
                                    &mut frames,
                                    BuildFrame::Visit(prefix, start),
                                )?,
                                None => push_end(function, budget, &mut ends, start)?,
                            }
                        }
                        ObservationDagKind::Cat(_) => {
                            push_end(function, budget, &mut ends, start)?;
                            push_frame(
                                function,
                                budget,
                                &mut frames,
                                BuildFrame::Cat(dag, start, 0),
                            )?;
                        }
                        ObservationDagKind::Alt(members) => {
                            push_frame(
                                function,
                                budget,
                                &mut frames,
                                BuildFrame::Alt(dag, start, members.len()),
                            )?;
                            for member in members {
                                push_frame(
                                    function,
                                    budget,
                                    &mut frames,
                                    BuildFrame::Visit(member, start),
                                )?;
                            }
                        }
                    }
                }
                BuildFrame::Seq(dag, start) => {
                    let ObservationDagKind::Seq(_, items) = &dag.kind else {
                        unreachable!("sequence frame holds a sequence node");
                    };
                    let prefix_end = ends.pop().expect("sequence prefix end retained");
                    budget.charge(function, items.len(), "factored HIR automaton")?;
                    let end = self.chain(function, budget, prefix_end, items)?;
                    memo_insert(function, budget, memo, key(dag, start), end)?;
                    push_end(function, budget, &mut ends, end)?;
                }
                BuildFrame::Cat(dag, start, index) => {
                    let ObservationDagKind::Cat(parts) = &dag.kind else {
                        unreachable!("concatenation frame holds a concatenation node");
                    };
                    let end = ends.pop().expect("concatenation part end retained");
                    match parts.get(index) {
                        Some(part) => {
                            push_frame(
                                function,
                                budget,
                                &mut frames,
                                BuildFrame::Cat(dag, start, index + 1),
                            )?;
                            push_frame(
                                function,
                                budget,
                                &mut frames,
                                BuildFrame::Visit(part, end),
                            )?;
                        }
                        None => {
                            memo_insert(function, budget, memo, key(dag, start), end)?;
                            push_end(function, budget, &mut ends, end)?;
                        }
                    }
                }
                BuildFrame::Alt(dag, start, count) => {
                    let join = self.node(function, budget)?;
                    for _ in 0..count {
                        let end = ends.pop().expect("union member end retained");
                        self.epsilon(function, budget, end, join)?;
                    }
                    memo_insert(function, budget, memo, key(dag, start), join)?;
                    push_end(function, budget, &mut ends, join)?;
                }
            }
        }
        Ok(ends.pop().expect("factored DAG build produced an end"))
    }

    fn add_plan(
        &mut self,
        function: &ResolvedFunction,
        success: usize,
        failure: usize,
        latch: usize,
        budget: &mut ReplayBudget,
    ) -> Result<usize, Diagnostic> {
        let plan = &function.cleanup_plan;
        budget.charge(
            function,
            plan_structure_units(plan),
            "factored cleanup-plan automaton",
        )?;
        budget.reserve_array::<usize>(
            function,
            plan.blocks.len(),
            "factored plan block entries",
        )?;
        let mut entries = Vec::with_capacity(plan.blocks.len());
        for _ in &plan.blocks {
            entries.push(self.node(function, budget)?);
        }
        let entry = |block: BlockId| entries[block.0 as usize];
        for (index, block) in plan.blocks.iter().enumerate() {
            let mut node = entries[index];
            for transition in &block.transitions {
                if let Some(observation) = transition_observation(function, budget, transition)? {
                    let next = self.node(function, budget)?;
                    self.observation(function, budget, node, observation, next)?;
                    node = next;
                }
            }
            match &block.terminator {
                CleanupTerminator::Goto(edge) => {
                    let edge = &plan.edges[edge.0 as usize];
                    let to = entry(edge.to);
                    if let EdgeCondition::VariantCase { .. } = &edge.condition {
                        let observation = edge_observation(function, budget, &edge.condition)?;
                        self.observation(function, budget, node, observation, to)?;
                    } else {
                        self.epsilon(function, budget, node, to)?;
                    }
                }
                CleanupTerminator::Branch(edges) => {
                    for edge in edges {
                        let edge = &plan.edges[edge.0 as usize];
                        let observation = edge_observation(function, budget, &edge.condition)?;
                        self.observation(function, budget, node, observation, entry(edge.to))?;
                    }
                }
                CleanupTerminator::Exit(exit) => {
                    let exit = &plan.exits[exit.0 as usize];
                    let target = match &exit.continuation {
                        ExitContinuation::Continue(edge) => entry(plan.edges[edge.0 as usize].to),
                        ExitContinuation::CommitResult { .. } | ExitContinuation::ReturnUnit => {
                            success
                        }
                        ExitContinuation::ReturnFailure { .. } => failure,
                        ExitContinuation::LoopBreak { edge, .. }
                        | ExitContinuation::FunctionReturn { edge, .. } => {
                            let marker =
                                lexical_skeleton::plan_exit_observation(budget, function, exit.id)?
                                    .ok_or_else(|| {
                                        replay_error(
                                    function,
                                    "factored lexical exit lacks an exact certificate marker",
                                )
                                    })?;
                            // The marker itself is the labelled continuation edge.
                            // A lexical exit must never become an epsilon edge.
                            self.observation(
                                function,
                                budget,
                                node,
                                marker,
                                entry(plan.edges[edge.0 as usize].to),
                            )?;
                            continue;
                        }
                        ExitContinuation::LoopLatch { target } => {
                            let marker = match lexical_skeleton::plan_exit_observation(
                                budget, function, exit.id,
                            )? {
                                Some(marker) => marker,
                                None => SkeletonObservation::LoopLatch {
                                    target: skeleton_clone(
                                        budget,
                                        function,
                                        target,
                                        "factored loop-latch target clone",
                                    )?,
                                },
                            };
                            let target =
                                lexical_cert::latch_resume(plan, exit.id).map_or(latch, entry);
                            self.observation(function, budget, node, marker, target)?;
                            continue;
                        }
                    };
                    self.epsilon(function, budget, node, target)?;
                }
            }
        }
        Ok(entry(plan.entry))
    }
}

/// The skeleton observation one cleanup transition contributes, exactly as
/// the enumerating `plan_skeleton_paths` records it.
fn transition_observation(
    function: &ResolvedFunction,
    budget: &mut ReplayBudget,
    transition: &CleanupTransition,
) -> Result<Option<SkeletonObservation>, Diagnostic> {
    reserve_transition_observation(function, budget, transition)?;
    Ok(Some(match transition {
        CleanupTransition::Initialize { at, destination }
        | CleanupTransition::InitializeVariant {
            at, destination, ..
        } => SkeletonObservation::Initialize {
            at: at.clone(),
            destination: destination.clone(),
        },
        CleanupTransition::ReserveRenewal { at, binding } => SkeletonObservation::ReserveRenewal {
            at: at.clone(),
            binding: binding.clone(),
        },
        CleanupTransition::Transfer {
            at,
            source,
            destination,
        }
        | CleanupTransition::Renew {
            at,
            source,
            destination,
        }
        | CleanupTransition::TransferVariant {
            at,
            source,
            destination,
            ..
        } => SkeletonObservation::Transfer {
            at: at.clone(),
            source: source.clone(),
            destination: destination.clone(),
        },
        CleanupTransition::CallCommit { call, arguments } => SkeletonObservation::CallCommit {
            call: call.clone(),
            arguments: arguments
                .iter()
                .map(|argument| (argument.parameter_index, argument.source.clone()))
                .collect(),
        },
        CleanupTransition::StageCopyResult { source } => {
            SkeletonObservation::StageCopyResult(source.clone())
        }
        CleanupTransition::AuthenticateVariantCase { .. }
        | CleanupTransition::SelectFailure { .. } => return Ok(None),
    }))
}

/// The skeleton observation one edge condition contributes, exactly as the
/// enumerating `plan_skeleton_paths` records it.
fn edge_observation(
    function: &ResolvedFunction,
    budget: &mut ReplayBudget,
    condition: &EdgeCondition,
) -> Result<SkeletonObservation, Diagnostic> {
    if let EdgeCondition::VariantCase { case, .. } = condition {
        budget.reserve_clone(function, case, "factored edge case identity")?;
    }
    Ok(match condition {
        EdgeCondition::BooleanResult(expression, value) => SkeletonObservation::Boolean {
            expression: expression.clone(),
            value: *value,
        },
        EdgeCondition::VariantCase {
            scrutinee,
            case,
            matches,
        } => SkeletonObservation::VariantCase {
            scrutinee: scrutinee.clone(),
            case: case.clone(),
            matches: *matches,
        },
        EdgeCondition::ArmSelected {
            scrutinee,
            arm,
            selected,
        } => SkeletonObservation::ArmSelected {
            scrutinee: scrutinee.clone(),
            arm: *arm,
            selected: *selected,
        },
        EdgeCondition::StatusZero(source) => SkeletonObservation::Status {
            source: source.clone(),
            success: true,
        },
        EdgeCondition::StatusNonzero(source) => SkeletonObservation::Status {
            source: source.clone(),
            success: false,
        },
        EdgeCondition::Always => {
            return Err(replay_error(
                function,
                "branch skeleton contains an unconditional edge",
            ));
        }
    })
}

/// A weighted set of automaton nodes: each node with the number of distinct
/// automaton paths that reach it on one observation sequence.
pub(in crate::cleanup_plan::replay::factored) type Weighted = Vec<(usize, u64)>;

