fn observe(
    function: &ResolvedFunction,
    old: bool,
    nodes: usize,
    fanout: usize,
    limit: usize,
) -> (
    (bool, crate::test_allocation_observer::Metrics),
    bool,
    usize,
    Option<crate::bounded_output::ReservationRefusal>,
) {
    with_limit_usage_refusal(limit, || {
        measure(|| {
            let mut budget = ReplayBudget::new();
            let result = (|| -> Result<(), Diagnostic> {
                if old {
                    let mut automaton = Automaton::default();
                    let mut previous = automaton.node(function, &mut budget)?;
                    for _ in 0..nodes {
                        let next = automaton.node(function, &mut budget)?;
                        for _ in 0..fanout {
                            automaton.movement(
                                function,
                                &mut budget,
                                previous,
                                Label::End(SkeletonTerminal::Success),
                                next,
                            )?;
                        }
                        previous = next;
                    }
                    drop(automaton);
                } else {
                    let mut automaton = current::Automaton::default();
                    let mut previous = automaton.node(function, &mut budget)?;
                    for _ in 0..nodes {
                        let next = automaton.node(function, &mut budget)?;
                        for _ in 0..fanout {
                            automaton.movement(
                                function,
                                &mut budget,
                                previous,
                                current::Label::End(SkeletonTerminal::Success),
                                next,
                            )?;
                        }
                        previous = next;
                    }
                    drop(automaton);
                }
                Ok(())
            })();
            let success = result.is_ok();
            drop(result);
            drop(budget);
            success
        })
    })
}

